<template>
  <div class="page-stack">
    <section class="hero compact">
      <div><span class="eyebrow">SCHEMATIC CONVERSATIONS</span><h1>原理图生成总览</h1><p>汇总 LiteLLM 中的评测与普通会话，并将主 Agent 和它创建的 Subagent 放在同一个会话中。</p></div>
    </section>

    <el-card shadow="never" class="panel search-panel">
      <el-tabs v-model="source" @tab-change="search()"><el-tab-pane label="全部会话" name="all"/><el-tab-pane label="评测会话" name="evaluation"/><el-tab-pane label="非评测会话" name="non_evaluation"/></el-tabs>
      <el-form label-position="top" @submit.prevent="search()"><div class="search-grid">
        <el-form-item label="LiteLLM End User"><el-select v-model="endUser" filterable clearable allow-create placeholder="全部 End User"><el-option v-for="item in filterOptions.end_users" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="会话 ID"><el-input v-model="sessionId" clearable placeholder="主会话或 Subagent session_id" @keyup.enter="search()"/></el-form-item>
        <el-form-item label="模型"><el-select v-model="selectedModel" filterable clearable placeholder="全部模型"><el-option v-for="item in filterOptions.models" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="检索"><el-button native-type="submit" type="primary" :loading="loading">搜索</el-button></el-form-item>
      </div></el-form>
      <p class="search-note">数据按根会话分页；一个主会话及其全部 Subagent 不会被拆到不同页。页面读取 LiteLLM 数据库中的全部来源。<span v-if="data.scan_truncated"> 当前数据量较大，列表基于最近 {{number(data.scanned_interactions)}} 次调用；可增加筛选条件缩小范围。</span></p>
    </el-card>

    <div class="overview-metrics"><div><span>匹配会话</span><b>{{number(data.total)}}</b></div><div><span>当前交互</span><b>{{number(pageInteractions)}}</b></div><div><span>当前 Token</span><b>{{number(pageTokens)}}</b></div><div><span>当前 Subagent</span><b>{{number(pageSubagents)}}</b></div></div>

    <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>会话列表</b><span>点击会话查看完整主 Agent / Subagent 交互</span></div><el-tag effect="plain">{{data.conversations?.length||0}} 条</el-tag></div></template>
      <div v-if="data.conversations?.length" class="conversation-grid">
        <article v-for="conversation in data.conversations" :key="conversation.root_session_id" :class="{active:selectedRoot===conversation.root_session_id}" @click="openConversation(conversation)">
          <header><el-tag size="small" :type="sourceType(conversation.source_kind)">{{sourceLabel(conversation.source_kind)}}</el-tag><span>{{formatTime(conversation.finished_at||conversation.started_at)}}</span></header>
          <b class="session-title">{{conversation.root_session_id}}</b><p>{{conversation.agent||'Agent 未记录'}} · {{conversation.models?.join('、')||'模型未记录'}}</p>
          <div class="card-stats"><span>{{number(conversation.interaction_count)}} 次调用</span><span>{{number(conversation.subagent_count)}} 个 Subagent</span><span>{{number(conversation.total_tokens)}} tokens</span></div><small>End User：{{conversation.end_user||'未记录'}}</small>
        </article>
      </div><el-empty v-else description="没有找到匹配的会话"/><div v-if="data.has_more" class="load-more"><el-button :loading="loading" @click="search(true)">加载更多会话</el-button></div>
    </el-card>

    <el-card v-if="detailLoading||detail" v-loading="detailLoading" shadow="never" class="panel detail-panel"><template #header><div class="section-head"><div><b>会话详情</b><span>{{detail?.root_session_id||selectedRoot}}</span></div><el-radio-group v-model="detailView" size="small"><el-radio-button value="timeline">合并时间线</el-radio-button><el-radio-button value="sessions">会话树</el-radio-button></el-radio-group></div></template>
      <div v-if="detail&&detailView==='sessions'" class="session-tree"><article v-for="node in detail.sessions" :key="node.session_id" :style="{marginLeft:`${Math.min(node.depth,6)*28}px`}"><span class="tree-line">{{node.depth?'SUBAGENT':'MAIN AGENT'}}</span><div><b>{{node.session_id}}</b><small v-if="node.parent_session_id">父会话：{{node.parent_session_id}}</small></div><div class="tree-stats"><span>{{node.interaction_count}} 次调用</span><span>{{number(node.total_tokens)}} tokens</span><span>{{node.models?.join('、')||'模型未记录'}}</span></div></article></div>
      <div v-if="detail&&detailView==='timeline'" class="interaction-list">
        <article v-for="(item,index) in detail.timeline" :key="item.request_id||index" class="interaction-card" :class="{subagent:item.depth>0}">
          <header><span class="sequence">{{index+1}}</span><div><b>{{item.model_group||item.model||'未知模型'}}</b><small>{{formatTime(item.start_time)}} · {{roleName(item)}} · {{item.session_id}}</small></div><div class="request-meta"><el-tag size="small" :type="item.status==='success'?'success':'danger'">{{item.status||'未知状态'}}</el-tag><span>{{duration(item.request_duration_ms)}}</span><span>{{number(item.total_tokens)}} tokens</span></div></header>
          <div class="conversation">
            <div v-for="(message,mIndex) in requestMessages(item)" :key="`m-${mIndex}`" class="message" :class="roleClass(message.role)"><span class="role">{{roleLabel(message.role)}}</span><div><p>{{contentText(message.content)}}</p><div v-if="message.tool_calls?.length" class="tool-list"><div v-for="tool in message.tool_calls" :key="tool.id||tool.function?.name"><b>工具调用 · {{tool.function?.name||tool.name}}</b><pre>{{readable(tool.function?.arguments||tool.arguments)}}</pre></div></div></div></div>
            <div v-for="(message,rIndex) in responseMessages(item)" :key="`r-${rIndex}`" class="message assistant"><span class="role">AGENT</span><div><p>{{contentText(message.content)}}</p><div v-if="message.tool_calls?.length" class="tool-list"><div v-for="tool in message.tool_calls" :key="tool.id||tool.function?.name"><b>工具调用 · {{tool.function?.name||tool.name}}</b><pre>{{readable(tool.function?.arguments||tool.arguments)}}</pre></div></div></div></div>
            <div v-if="errorText(item)" class="message error"><span class="role">ERROR</span><div><p>{{errorText(item)}}</p></div></div>
          </div><footer><span>请求 {{item.request_id}}</span><span>层级 {{item.depth||0}}</span><span>输入 {{number(item.prompt_tokens)}} / 输出 {{number(item.completion_tokens)}}</span><span>工具 {{number(item.tool_call_count)}}</span></footer><details class="raw-log"><summary>完整请求 / 响应 / 元数据</summary><pre>{{JSON.stringify(item,null,2)}}</pre></details>
        </article>
      </div>
    </el-card>
  </div>
</template>

<script setup>
import {computed,onMounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {fetchSchematicConversation,fetchSchematicConversations,fetchSchematicInteractionFilters} from '../api'

const endUser=ref(''),sessionId=ref(''),selectedModel=ref(''),source=ref('all'),loading=ref(false),detailLoading=ref(false),selectedRoot=ref(''),detail=ref(null),detailView=ref('timeline')
const data=ref({total:0,conversations:[]}),filterOptions=ref({end_users:[],models:[]})
const pageInteractions=computed(()=>(data.value.conversations||[]).reduce((sum,item)=>sum+Number(item.interaction_count||0),0))
const pageTokens=computed(()=>(data.value.conversations||[]).reduce((sum,item)=>sum+Number(item.total_tokens||0),0))
const pageSubagents=computed(()=>(data.value.conversations||[]).reduce((sum,item)=>sum+Number(item.subagent_count||0),0))
async function search(append=false){if(loading.value)return;append=append===true;loading.value=true;try{const next=await fetchSchematicConversations({end_user:endUser.value.trim()||undefined,session_id:sessionId.value.trim()||undefined,model:selectedModel.value||undefined,source:source.value,limit:30,offset:append?data.value.next_offset:0});if(append)next.conversations=[...data.value.conversations,...next.conversations];data.value=next;if(!append){detail.value=null;selectedRoot.value=''}}catch(error){ElMessage.error(error.response?.data?.detail||error.message)}finally{loading.value=false}}
async function openConversation(conversation){selectedRoot.value=conversation.root_session_id;detailLoading.value=true;try{detail.value=await fetchSchematicConversation(conversation.root_session_id)}catch(error){ElMessage.error(error.response?.data?.detail||error.message)}finally{detailLoading.value=false}}
onMounted(async()=>{try{filterOptions.value=await fetchSchematicInteractionFilters()}catch{}await search()})
function objectValue(value){if(typeof value==='string'){try{return JSON.parse(value)}catch{return value}}return value}
function requestMessages(item){const raw=objectValue(item.proxy_server_request)||{},request=objectValue(raw.body)||raw,messages=objectValue(request.messages||item.messages||request.input);return Array.isArray(messages)?messages.map(m=>typeof m==='string'?{role:'user',content:m}:m):typeof messages==='string'?[{role:'user',content:messages}]:[]}
function responseMessages(item){const response=objectValue(item.response)||{};if(Array.isArray(response.choices))return response.choices.map(choice=>choice.message||choice.delta).filter(Boolean);if(Array.isArray(response.output))return response.output.map(item=>({role:item.role||'assistant',content:item.content||item.summary||item,tool_calls:item.type==='function_call'?[item]:[]}));return response.content?[{role:'assistant',content:response.content}]:[]}
function contentText(value){if(value==null||value==='')return'（无文本内容）';if(typeof value==='string')return value;if(Array.isArray(value))return value.map(part=>typeof part==='string'?part:(part.text||part.content||part.type||readable(part))).join('\n');return readable(value)}
function readable(value){if(value==null)return'—';if(typeof value==='string'){try{return readable(JSON.parse(value))}catch{return value}}if(Array.isArray(value))return value.map(readable).join('\n');return Object.entries(value).map(([key,item])=>`${key}: ${typeof item==='object'?readable(item):item}`).join('\n')}
function errorText(item){return item.metadata?.error_information?.error_message||item.metadata?.error_information?.error||''}
function roleLabel(role){return({user:'用户',assistant:'Agent',system:'系统',tool:'工具'}[role]||role||'消息').toUpperCase()}
function roleClass(role){return['user','assistant','system','tool'].includes(role)?role:'system'}
function roleName(item){return item.depth?`Subagent L${item.depth}`:'主 Agent'}
function sourceLabel(value){return({evaluation:'评测',non_evaluation:'非评测',mixed:'混合'}[value]||value)}
function sourceType(value){return value==='evaluation'?'warning':value==='mixed'?'info':'success'}
const number=value=>value==null?'—':Number(value).toLocaleString(),duration=value=>value==null?'—':Number(value)>=1000?`${(Number(value)/1000).toFixed(1)} 秒`:`${value} ms`,formatTime=value=>value?new Date(value).toLocaleString('zh-CN'):'时间未记录'
</script>

<style scoped>
.search-panel :deep(.el-form-item){margin:0}.search-panel :deep(.el-select){width:100%}.search-grid{display:grid;grid-template-columns:1.15fr 1fr 1fr 110px;align-items:end;gap:14px}.search-grid .el-button{width:100%}.search-note{margin:12px 0 0;color:var(--muted);font-size:12px}.overview-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.overview-metrics>div{display:flex;flex-direction:column;padding:18px 20px;background:var(--surface);border:1px solid var(--line);border-radius:12px}.overview-metrics span{color:var(--muted);font-size:12px}.overview-metrics b{font-size:25px;margin-top:6px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.section-head>div{display:flex;flex-direction:column;gap:4px;min-width:0}.section-head span{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.conversation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.conversation-grid article{padding:15px;border:1px solid var(--line);border-radius:10px;cursor:pointer;transition:.18s}.conversation-grid article:hover,.conversation-grid article.active{border-color:var(--brand);background:var(--brand-soft)}.conversation-grid header{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:11px}.session-title{display:block;margin-top:12px;font-size:12px;overflow-wrap:anywhere}.conversation-grid p{margin:8px 0;color:var(--muted);font-size:12px}.conversation-grid small{color:var(--muted)}.card-stats{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:9px}.card-stats span,.tree-stats span{padding:3px 6px;border-radius:5px;background:var(--surface-2);font-size:11px}.load-more{display:flex;justify-content:center;margin-top:16px}.session-tree{display:grid;gap:10px}.session-tree article{display:grid;grid-template-columns:90px minmax(0,1fr) auto;gap:12px;align-items:center;padding:13px;border-left:3px solid var(--brand);background:var(--surface-2);border-radius:7px}.session-tree article>div{display:flex;flex-direction:column;gap:4px;min-width:0}.session-tree b,.session-tree small{overflow-wrap:anywhere}.session-tree small{color:var(--muted)}.tree-line{font-size:10px;font-weight:700;color:var(--brand)}.tree-stats{flex-direction:row!important;flex-wrap:wrap;justify-content:flex-end}.interaction-list{display:grid;gap:14px}.interaction-card{border:1px solid var(--line);border-radius:11px;overflow:hidden}.interaction-card.subagent{border-left:4px solid #d6a23b}.interaction-card>header{display:grid;grid-template-columns:32px minmax(0,1fr) auto;align-items:center;gap:10px;padding:13px 16px;background:var(--surface-2)}.sequence{display:grid;place-items:center;width:27px;height:27px;border-radius:50%;background:var(--brand-soft);color:var(--brand);font-weight:700;font-size:12px}.interaction-card header div{display:flex;flex-direction:column}.interaction-card header small{color:var(--muted);font-size:11px;margin-top:3px;overflow-wrap:anywhere}.request-meta{flex-direction:row!important;align-items:center;gap:12px;color:var(--muted);font-size:12px}.conversation{display:grid;gap:10px;padding:16px}.message{display:grid;grid-template-columns:72px minmax(0,1fr);gap:12px;padding:13px 15px;border-radius:9px;background:var(--surface-2)}.message.user{background:#f0f6ff}.message.assistant{background:var(--brand-soft)}.message.tool{background:#fff8e8}.message.error{background:#fff0f0;color:var(--danger)}.message .role{font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--muted)}.message p{margin:0;white-space:pre-wrap;line-height:1.65;overflow-wrap:anywhere}.tool-list{display:grid;gap:8px;margin-top:10px}.tool-list>div{border-left:3px solid #d6a23b;padding:8px 10px;background:rgba(255,255,255,.58)}.tool-list pre,.raw-log pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.interaction-card>footer{display:flex;gap:18px;flex-wrap:wrap;padding:10px 16px;border-top:1px solid var(--line);color:var(--muted);font-size:11px}.raw-log{padding:16px}.raw-log pre{max-height:700px;overflow:auto}@media(max-width:1000px){.conversation-grid{grid-template-columns:1fr 1fr}.session-tree article{grid-template-columns:80px 1fr}.tree-stats{grid-column:2;justify-content:flex-start}}@media(max-width:900px){.search-grid,.overview-metrics{grid-template-columns:1fr 1fr}.search-grid>:last-child{grid-column:1/-1}.interaction-card>header{grid-template-columns:32px 1fr}.request-meta{grid-column:2;justify-content:flex-start}.message{grid-template-columns:1fr}}@media(max-width:600px){.search-grid,.overview-metrics,.conversation-grid{grid-template-columns:1fr}.search-grid>:last-child{grid-column:auto}.section-head{align-items:flex-start;flex-direction:column}.session-tree article{margin-left:0!important;grid-template-columns:1fr}.tree-stats{grid-column:auto}}
</style>
